INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000841', 'Tujuan utama polymer flooding adalah...', 'The main purpose of polymer flooding is...', 'option', 'PFC000000009', 'Inisialisasi', 'a:4:{i:0;s:20:"Menurunkan porositas";i:1;s:26:"Menurunkan tekanan injeksi";i:2;s:46:"Memperbaiki mobility ratio dan efisiensi sweep";i:3;s:28:"Menaikkan tegangan antarmuka";}', 'a:4:{i:0;s:15:"Reduce porosity";i:1;s:24:"Lower injection pressure";i:2;s:47:"Improve the mobility ratio and sweep efficiency";i:3;s:28:"Increase interfacial tension";}', '', 'Memperbaiki mobility ratio dan efisiensi sweep', 'Improve the mobility ratio and sweep efficiency', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000842', 'Jenis polimer yang paling umum digunakan adalah...', 'The most commonly used polymer type is...', 'option', 'PFC000000009', 'Inisialisasi', 'a:4:{i:0;s:4:"NaCl";i:1;s:12:"Gas nitrogen";i:2;s:11:"Asam sulfat";i:3;s:32:"HPAM (hydrolyzed polyacrylamide)";}', 'a:4:{i:0;s:4:"NaCl";i:1;s:12:"Nitrogen gas";i:2;s:13:"Sulfuric acid";i:3;s:32:"HPAM (hydrolyzed polyacrylamide)";}', '', 'HPAM (hydrolyzed polyacrylamide)', 'HPAM (hydrolyzed polyacrylamide)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
