INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000844', 'Adsorpsi polimer pada permukaan batuan menyebabkan...', 'Polymer adsorption on the rock surface causes...', 'option', 'PFC000000009', 'Inisialisasi', 'a:4:{i:0;s:27:"Penurunan viskositas minyak";i:1;s:33:"Peningkatan permeabilitas absolut";i:2;s:53:"Kehilangan sebagian polimer dan penurunan efektivitas";i:3;s:21:"Peningkatan porositas";}', 'a:4:{i:0;s:21:"Reduced oil viscosity";i:1;s:31:"Increased absolute permeability";i:2;s:46:"Loss of some polymer and reduced effectiveness";i:3;s:18:"Increased porosity";}', '', 'Kehilangan sebagian polimer dan penurunan efektivitas', 'Loss of some polymer and reduced effectiveness', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000845', 'Degradasi shear pada polimer terjadi akibat...', 'Shear degradation of polymer occurs due to...', 'option', 'PFC000000009', 'Inisialisasi', 'a:4:{i:0;s:46:"Gaya geser tinggi saat melewati pompa dan pori";i:1;s:16:"Penambahan garam";i:2;s:19:"Pemanasan reservoir";i:3;s:19:"Pengurangan tekanan";}', 'a:4:{i:0;s:54:"High shear forces when passing through pumps and pores";i:1;s:13:"Salt addition";i:2;s:17:"Reservoir heating";i:3;s:18:"Pressure reduction";}', '', 'Gaya geser tinggi saat melewati pompa dan pori', 'High shear forces when passing through pumps and pores', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
