INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000847', 'Manakah persyaratan air untuk pencampuran polimer?', 'Which are water requirements for polymer mixing?', 'multi', 'PFC000000009', 'Inisialisasi', 'a:4:{i:0;s:17:"Kadar besi rendah";i:1;s:19:"Kadar minyak tinggi";i:2;s:20:"Kadar oksigen rendah";i:3;s:20:"Salinitas terkontrol";}', 'a:4:{i:0;s:16:"Low iron content";i:1;s:16:"High oil content";i:2;s:18:"Low oxygen content";i:3;s:19:"Controlled salinity";}', '', 'a:3:{i:0;s:20:"Kadar oksigen rendah";i:1;s:17:"Kadar besi rendah";i:2;s:20:"Salinitas terkontrol";}', 'a:3:{i:0;s:18:"Low oxygen content";i:1;s:16:"Low iron content";i:2;s:19:"Controlled salinity";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000848', 'Urutkan proses polymer flooding dari persiapan sampai produksi.', 'Arrange the polymer flooding process from preparation to production.', 'drag', 'PFC000000009', 'Inisialisasi', 'a:6:{i:0;s:21:"Persiapan air injeksi";i:1;s:19:"Pencampuran polimer";i:2;s:36:"Injeksi larutan polimer ke reservoir";i:3;s:38:"Perbaikan sweep dan pendorongan minyak";i:4;s:33:"Produksi minyak di sumur produksi";i:5;s:18:"Pembakaran in-situ";}', 'a:6:{i:0;s:27:"Injection water preparation";i:1;s:14:"Polymer mixing";i:2;s:45:"Polymer solution injection into the reservoir";i:3;s:38:"Sweep improvement and oil displacement";i:4;s:35:"Oil production at the producer well";i:5;s:18:"In-situ combustion";}', '', 'a:5:{i:0;s:21:"Persiapan air injeksi";i:1;s:19:"Pencampuran polimer";i:2;s:36:"Injeksi larutan polimer ke reservoir";i:3;s:38:"Perbaikan sweep dan pendorongan minyak";i:4;s:33:"Produksi minyak di sumur produksi";}', 'a:5:{i:0;s:27:"Injection water preparation";i:1;s:14:"Polymer mixing";i:2;s:45:"Polymer solution injection into the reservoir";i:3;s:38:"Sweep improvement and oil displacement";i:4;s:35:"Oil production at the producer well";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000849', 'Benarkah polymer flooding menurunkan tegangan antarmuka secara signifikan seperti surfaktan?', 'Is it true that polymer flooding significantly reduces interfacial tension like a surfactant?', 'yesorno', 'PFC000000009', 'Inisialisasi', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'No', 'No', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000850', 'Jika viskositas air dinaikkan dari 1 cp menjadi 20 cp sementara viskositas minyak 40 cp, mobility ratio air-minyak berubah dari 40 menjadi...', 'If water viscosity is increased from 1 cp to 20 cp while oil viscosity is 40 cp, the water-oil mobility ratio changes from 40 to...', 'option', 'PFC000000009', 'Final Advanced', 'a:4:{i:0;s:3:"800";i:1;s:2:"20";i:2;s:1:"2";i:3;s:2:"40";}', 'a:4:{i:0;s:3:"800";i:1;s:2:"20";i:2;s:1:"2";i:3;s:2:"40";}', '', '2', '2', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000851', 'Resistance factor (RF) pada polymer flooding didefinisikan sebagai...', 'The resistance factor (RF) in polymer flooding is defined as...', 'option', 'PFC000000009', 'Final Advanced', 'a:4:{i:0;s:31:"Rasio viskositas minyak dan gas";i:1;s:27:"Rasio tekanan dan laju alir";i:2;s:33:"Rasio porositas dan permeabilitas";i:3;s:47:"Rasio mobilitas air sebelum dan sesudah polimer";}', 'a:4:{i:0;s:34:"The ratio of oil and gas viscosity";i:1;s:34:"The ratio of pressure to flow rate";i:2;s:37:"The ratio of porosity to permeability";i:3;s:52:"The ratio of water mobility before and after polymer";}', '', 'Rasio mobilitas air sebelum dan sesudah polimer', 'The ratio of water mobility before and after polymer', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000852', 'Residual resistance factor (RRF) berkaitan dengan...', 'The residual resistance factor (RRF) relates to...', 'option', 'PFC000000009', 'Final Advanced', 'a:4:{i:0;s:29:"Peningkatan tekanan reservoir";i:1;s:62:"Penurunan permeabilitas air yang tersisa setelah polimer lewat";i:2;s:27:"Penurunan viskositas minyak";i:3;s:21:"Peningkatan porositas";}', 'a:4:{i:0;s:28:"Increased reservoir pressure";i:1;s:66:"The remaining reduction in water permeability after polymer passes";i:2;s:21:"Reduced oil viscosity";i:3;s:18:"Increased porosity";}', '', 'Penurunan permeabilitas air yang tersisa setelah polimer lewat', 'The remaining reduction in water permeability after polymer passes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000853', 'Kurva adsorpsi polimer umumnya berbentuk...', 'The polymer adsorption curve is generally shaped...', 'option', 'PFC000000009', 'Final Advanced', 'a:4:{i:0;s:20:"Eksponensial menurun";i:1;s:43:"Langmuir (mendatar pada konsentrasi tinggi)";i:2;s:25:"Parabola terbuka ke bawah";i:3;s:18:"Linier tanpa batas";}', 'a:4:{i:0;s:24:"Exponentially decreasing";i:1;s:45:"Langmuir (leveling off at high concentration)";i:2;s:25:"Downward-opening parabola";i:3;s:16:"Unbounded linear";}', '', 'Langmuir (mendatar pada konsentrasi tinggi)', 'Langmuir (leveling off at high concentration)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000854', 'Inaccessible pore volume (IPV) menyebabkan...', 'Inaccessible pore volume (IPV) causes...', 'option', 'PFC000000009', 'Final Advanced', 'a:4:{i:0;s:55:"Polimer bergerak lebih cepat dari air pada awal injeksi";i:1;s:34:"Viskositas polimer meningkat tajam";i:2;s:40:"Polimer tidak dapat mengalir sama sekali";i:3;s:20:"Adsorpsi menjadi nol";}', 'a:4:{i:0;s:59:"Polymer to move faster than water at the start of injection";i:1;s:37:"Polymer viscosity to increase sharply";i:2;s:35:"Polymer to be unable to flow at all";i:3;s:25:"Adsorption to become zero";}', '', 'Polimer bergerak lebih cepat dari air pada awal injeksi', 'Polymer to move faster than water at the start of injection', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
