INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000857', 'Laju injeksi polimer yang terlalu tinggi berisiko...', 'A polymer injection rate that is too high risks...', 'option', 'PFC000000009', 'Final Advanced', 'a:4:{i:0;s:27:"Penurunan viskositas minyak";i:1;s:19:"Porositas meningkat";i:2;s:51:"Terbentuknya rekah (fracturing) dan degradasi shear";i:3;s:33:"Peningkatan adsorpsi hingga jenuh";}', 'a:4:{i:0;s:21:"Reduced oil viscosity";i:1;s:19:"Porosity increasing";i:2;s:32:"Fracturing and shear degradation";i:3;s:35:"Adsorption increasing to saturation";}', '', 'Terbentuknya rekah (fracturing) dan degradasi shear', 'Fracturing and shear degradation', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000858', 'Konsentrasi polimer yang dinaikkan umumnya menyebabkan...', 'Increasing polymer concentration generally causes...', 'option', 'PFC000000009', 'Final Advanced', 'a:4:{i:0;s:26:"Viskositas larutan menurun";i:1;s:20:"Adsorpsi menjadi nol";i:2;s:30:"Permeabilitas batuan meningkat";i:3;s:28:"Viskositas larutan meningkat";}', 'a:4:{i:0;s:30:"Solution viscosity to decrease";i:1;s:25:"Adsorption to become zero";i:2;s:29:"Rock permeability to increase";i:3;s:30:"Solution viscosity to increase";}', '', 'Viskositas larutan meningkat', 'Solution viscosity to increase', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000859', 'Slug polimer biasanya diikuti oleh...', 'The polymer slug is usually followed by...', 'option', 'PFC000000009', 'Final Advanced', 'a:4:{i:0;s:15:"Surfaktan pekat";i:1;s:5:"Semen";i:2;s:7:"Gas CO2";i:3;s:36:"Air chase water untuk mendorong slug";}', 'a:4:{i:0;s:23:"Concentrated surfactant";i:1;s:6:"Cement";i:2;s:7:"CO2 gas";i:3;s:28:"Chase water to push the slug";}', '', 'Air chase water untuk mendorong slug', 'Chase water to push the slug', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000860', 'Kehilangan polimer akibat adsorpsi paling besar pada batuan dengan...', 'Polymer loss due to adsorption is greatest in rock with...', 'option', 'PFC000000009', 'Final Advanced', 'a:4:{i:0;s:23:"Porositas sangat rendah";i:1;s:27:"Permeabilitas sangat tinggi";i:2;s:47:"Luas permukaan spesifik tinggi (banyak lempung)";i:3;s:22:"Kandungan kuarsa murni";}', 'a:4:{i:0;s:17:"Very low porosity";i:1;s:22:"Very high permeability";i:2;s:46:"High specific surface area (high clay content)";i:3;s:19:"Pure quartz content";}', '', 'Luas permukaan spesifik tinggi (banyak lempung)', 'High specific surface area (high clay content)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000861', 'Keberhasilan polymer flooding paling sensitif terhadap...', 'The success of polymer flooding is most sensitive to...', 'option', 'PFC000000009', 'Final Advanced', 'a:4:{i:0;s:18:"Jenis casing sumur";i:1;s:15:"Kedalaman sumur";i:2;s:12:"Warna minyak";i:3;s:51:"Kualitas air, salinitas, dan shear saat pencampuran";}', 'a:4:{i:0;s:16:"Well casing type";i:1;s:10:"Well depth";i:2;s:9:"Oil color";i:3;s:48:"Water quality, salinity, and shear during mixing";}', '', 'Kualitas air, salinitas, dan shear saat pencampuran', 'Water quality, salinity, and shear during mixing', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
