INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000863', 'Manakah kelebihan polymer flooding?', 'Which are advantages of polymer flooding?', 'multi', 'PFC000000009', 'Final Advanced', 'a:4:{i:0;s:46:"Teknologi relatif matang dan banyak diterapkan";i:1;s:43:"Cocok untuk minyak dengan viskositas sedang";i:2;s:33:"Dapat memperbaiki efisiensi sweep";i:3;s:35:"Dapat menurunkan IFT secara drastis";}', 'a:4:{i:0;s:57:"Relatively mature technology with many field applications";i:1;s:33:"Suitable for medium-viscosity oil";i:2;s:28:"Can improve sweep efficiency";i:3;s:26:"Can drastically reduce IFT";}', '', 'a:3:{i:0;s:46:"Teknologi relatif matang dan banyak diterapkan";i:1;s:33:"Dapat memperbaiki efisiensi sweep";i:2;s:43:"Cocok untuk minyak dengan viskositas sedang";}', 'a:3:{i:0;s:57:"Relatively mature technology with many field applications";i:1;s:28:"Can improve sweep efficiency";i:2;s:33:"Suitable for medium-viscosity oil";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
