INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000865', 'Manakah pernyataan yang benar tentang mobility ratio pada polymer flooding?', 'Which statements about mobility ratio in polymer flooding are correct?', 'multi', 'PFC000000009', 'Final Advanced', 'a:4:{i:0;s:35:"M dipengaruhi relative permeability";i:1;s:33:"M < 1 menunjukkan sweep yang baik";i:2;s:34:"M tidak bergantung pada viskositas";i:3;s:39:"Peningkatan viskositas air menurunkan M";}', 'a:4:{i:0;s:38:"M is affected by relative permeability";i:1;s:26:"M < 1 indicates good sweep";i:2;s:30:"M does not depend on viscosity";i:3;s:35:"Increasing water viscosity lowers M";}', '', 'a:3:{i:0;s:33:"M < 1 menunjukkan sweep yang baik";i:1;s:39:"Peningkatan viskositas air menurunkan M";i:2;s:35:"M dipengaruhi relative permeability";}', 'a:3:{i:0;s:26:"M < 1 indicates good sweep";i:1;s:35:"Increasing water viscosity lowers M";i:2;s:38:"M is affected by relative permeability";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
